candidates.raw:
size_t i;
int valid = 1;
double max_abs = 0.0;
double ideal[4];
double max_speed;
adcs_vec3_t h;
double power = 0.0;
int tripped;

wo_output.mode = wo_state.mode;
wo_output.limited_mask = 0U;

if ((wo_input.enable != 0) && (wo_input.enable != 1)) valid = 0;
if (wo_input.wheel_count != 4U) valid = 0;
if (!isfinite(wo_config.release_rad_s) || !isfinite(wo_config.warn_rad_s) ||
    !isfinite(wo_config.trip_rad_s) || !isfinite(wo_config.derate_torque_nm) ||
    !isfinite(wo_config.brake_torque_nm) || !isfinite(wo_config.torque_slew_nm_per_cycle) ||
    !isfinite(wo_config.dt_s))
    valid = 0;
if (!(wo_config.release_rad_s >= 0.0)) valid = 0;
if (!(wo_config.release_rad_s < wo_config.warn_rad_s)) valid = 0;
if (!(wo_config.warn_rad_s < wo_config.trip_rad_s)) valid = 0;
if (!(wo_config.derate_torque_nm > 0.0)) valid = 0;
if (!(wo_config.brake_torque_nm > 0.0)) valid = 0;
if (!(wo_config.brake_torque_nm >= wo_config.derate_torque_nm)) valid = 0;
if (!(wo_config.torque_slew_nm_per_cycle > 0.0)) valid = 0;
if (!(wo_config.dt_s > 0.0)) valid = 0;
if ((wo_config.release_cycles < 1U) || (wo_config.release_cycles > 100U)) valid = 0;
if ((wo_config.minimum_brake_cycles < 1U) || (wo_config.minimum_brake_cycles > 100U)) valid = 0;
if ((wo_config.cooldown_cycles < 1U) || (wo_config.cooldown_cycles > 100U)) valid = 0;

if (valid != 0) {
    if (adcs_wheel_momentum(wo_input.wheels, wo_input.wheel_count, &h) != ADCS_OK) valid = 0;
    else if (!isfinite(h.x) || !isfinite(h.y) || !isfinite(h.z)) valid = 0;
}
if (valid != 0) {
    for (i = 0; i < 4U; i++) {
        double sp;
        if (!isfinite(wo_input.wheels[i].speed_rad_s) ||
            !isfinite(wo_input.wheels[i].inertia_kg_m2) ||
            (wo_input.wheels[i].inertia_kg_m2 < 0.0)) {
            valid = 0;
            break;
        }
        sp = fabs(wo_input.wheels[i].speed_rad_s);
        if (sp > max_abs) max_abs = sp;
    }
}

if (valid == 0) {
    wo_state.mode = WO_FAULT;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
    wo_state.dissipated_energy_j = 0.0;
    for (i = 0; i < 4U; i++) wo_state.previous_wheel_torque_nm[i] = 0.0;
    for (i = 0; i < 4U; i++) wo_output.wheel_torque_nm[i] = 0.0;
    wo_output.mode = WO_FAULT;
    wo_output.clean = 0U;
    wo_output.elapsed = 0U;
    wo_output.limited_mask = 0U;
    wo_output.maximum_speed_rad_s = max_abs;
    wo_output.brake_power_w = 0.0;
    wo_output.dissipated_energy_j = 0.0;
    wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm_nms = 0.0;
    return;
}

max_speed = max_abs;
for (i = 0; i < 4U; i++) ideal[i] = 0.0;
tripped = (max_abs >= wo_config.trip_rad_s) ? 1 : 0;

if (wo_state.mode == WO_FAULT) {
    wo_state.mode = WO_NORMAL;
    wo_state.clean = 0U;
    wo_state.elapsed = 0U;
}

if (wo_state.mode == WO_NORMAL) {
    if (tripped) {
        wo_state.mode = WO_BRAKE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else if (max_abs >= wo_config.warn_rad_s) {
        wo_state.mode = WO_DERATE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    }
}

if (wo_state.mode == WO_DERATE) {
    if (tripped) {
        wo_state.mode = WO_BRAKE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else {
        for (i = 0; i < 4U; i++) {
            double sp = fabs(wo_input.wheels[i].speed_rad_s);
            double mag = 0.0;
            if (sp > wo_config.release_rad_s) {
                mag = wo_config.derate_torque_nm * (sp - wo_config.release_rad_s) /
                      (wo_config.trip_rad_s - wo_config.release_rad_s);
                if (mag > wo_config.derate_torque_nm) mag = wo_config.derate_torque_nm;
            }
            if (wo_input.wheels[i].speed_rad_s != 0.0)
                ideal[i] = -copysign(mag, wo_input.wheels[i].speed_rad_s);
            else
                ideal[i] = 0.0;
        }
        if (max_abs <= wo_config.release_rad_s) {
            if (wo_state.clean < 0xFFFFFFFFU) wo_state.clean++;
        } else {
            wo_state.clean = 0U;
        }
        if (wo_state.clean >= wo_config.release_cycles) {
            wo_state.mode = WO_NORMAL;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else {
            wo_state.elapsed++;
        }
    }
}

if (wo_state.mode == WO_BRAKE) {
    for (i = 0; i < 4U; i++) {
        if (wo_input.wheels[i].speed_rad_s != 0.0)
            ideal[i] = -copysign(wo_config.brake_torque_nm, wo_input.wheels[i].speed_rad_s);
        else
            ideal[i] = 0.0;
    }
    if (wo_state.elapsed < wo_config.minimum_brake_cycles) {
        wo_state.clean = 0U;
        wo_state.elapsed++;
    } else {
        if (max_abs <= wo_config.release_rad_s) {
            if (wo_state.clean < 0xFFFFFFFFU) wo_state.clean++;
        } else {
            wo_state.clean = 0U;
        }
        if (wo_state.clean >= wo_config.release_cycles) {
            wo_state.mode = WO_COOLDOWN;
            wo_state.clean = 0U;
            wo_state.elapsed = 0U;
        } else {
            wo_state.elapsed++;
        }
    }
}

if (wo_state.mode == WO_COOLDOWN) {
    for (i = 0; i < 4U; i++) ideal[i] = 0.0;
    if (tripped) {
        wo_state.mode = WO_BRAKE;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else if (wo_state.elapsed >= wo_config.cooldown_cycles) {
        wo_state.mode = WO_NORMAL;
        wo_state.clean = 0U;
        wo_state.elapsed = 0U;
    } else {
        wo_state.elapsed++;
    }
}

wo_output.limited_mask = 0U;
for (i = 0; i < 4U; i++) {
    double prev = wo_state.previous_wheel_torque_nm[i];
    double delta = ideal[i] - prev;
    int limited = 0;
    if (delta > wo_config.torque_slew_nm_per_cycle) {
        delta = wo_config.torque_slew_nm_per_cycle;
        limited = 1;
    }
    if (delta < -wo_config.torque_slew_nm_per_cycle) {
        delta = -wo_config.torque_slew_nm_per_cycle;
        limited = 1;
    }
    wo_output.wheel_torque_nm[i] = prev + delta;
    wo_state.previous_wheel_torque_nm[i] = wo_output.wheel_torque_nm[i];
    if (limited) wo_output.limited_mask |= (1U << i);
}

for (i = 0; i < 4U; i++) power += wo_output.wheel_torque_nm[i] * wo_input.wheels[i].speed_rad_s;

wo_output.brake_power_w = -power;
wo_state.dissipated_energy_j += (-power) * wo_config.dt_s;
wo_output.dissipated_energy_j = wo_state.dissipated_energy_j;
wo_output.maximum_speed_rad_s = max_speed;

if (adcs_wheel_momentum(wo_input.wheels, wo_input.wheel_count, &h) == ADCS_OK) {
    wo_output.momentum_nms = h;
    wo_output.momentum_norm_nms = adcs_vec3_norm(&h);
} else {
    wo_output.momentum_nms = (adcs_vec3_t){0, 0, 0};
    wo_output.momentum_norm_nms = 0.0;
}

wo_output.mode = wo_state.mode;
wo_output.clean = wo_state.clean;
wo_output.elapsed = wo_state.elapsed;

